public class WorkbenchReview : MonoBehaviour {
 const BindingFlags Private=BindingFlags.NonPublic|BindingFlags.Instance;
 Workbench ui;EditorWindow view;Type viewType;int width=1280,height=720;List<string> passed=new List<string>();
 T Get<T>(string name)=>(T)typeof(Workbench).GetField(name,Private).GetValue(ui);
 void Set(string name,object value)=>typeof(Workbench).GetField(name,Private).SetValue(ui,value);
 void Call(string name,params object[] values)=>typeof(Workbench).GetMethod(name,Private).Invoke(ui,values);
 Draft Data=>Get<Draft>("draft");
 void Assert(bool condition,string title){if(!condition){Capture("Failure");throw new Exception("FAILED: "+title);}passed.Add("PASS: "+title);}
 RenderTexture Render(){view.position=new Rect(0,0,width,height+21);viewType.GetProperty("targetSize",BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance).SetValue(view,new Vector2(width,height));view.SendEvent(new Event{type=EventType.Repaint});return (RenderTexture)viewType.GetMethod("RenderView",Private|BindingFlags.Public).Invoke(view,new object[]{Vector2.zero,false});}
 void Capture(string name){Render();var rt=Render();if(!rt)throw new Exception("Offscreen render unavailable");if(rt.width!=width||rt.height!=height)throw new Exception("Unexpected offscreen dimensions");var previous=RenderTexture.active;RenderTexture.active=rt;var image=new Texture2D(rt.width,rt.height,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,rt.width,rt.height),0,0);var source=image.GetPixels();var flipped=new Color[source.Length];for(int y=0;y<rt.height;y++)Array.Copy(source,y*rt.width,flipped,(rt.height-1-y)*rt.width,rt.width);image.SetPixels(flipped);image.Apply();File.WriteAllBytes("Docs/IslandSystem/"+name+".png",image.EncodeToPNG());RenderTexture.active=previous;Destroy(image);}
 void Send(Event e){ui.ReviewEvents.Enqueue(e);Render();if(ui.ReviewEvents.Count!=0)throw new Exception("UI event was not consumed");}
 void Pointer(EventType type,Vector2 p,int button=0){Send(new Event{type=type,mousePosition=p,button=button});}
 void Click(Vector2 p,int button=0){Pointer(EventType.MouseDown,p,button);Pointer(EventType.MouseUp,p,button);Render();}
 Vector2 Header(Block b,float y=.7f){var r=Get<Dictionary<Block,Rect>>("rects")[b];return new Vector2(395+r.x+30,110+r.y+r.height*y);}
 Vector2 Slot(Block b){var r=Get<Dictionary<Block,Rect>>("slots")[b];return new Vector2(395+r.x+30,110+r.center.y);}
 void Drag(int kind,Vector2 destination){int[] cats={0,1,2,2,2,3,4,5};int category=cats[kind];Click(new Vector2(140,130+category*38));int row=Enumerable.Range(0,kind).Count(i=>cats[i]==category);Pointer(EventType.MouseDown,new Vector2(230,140+row*64));Pointer(EventType.MouseDrag,destination);Pointer(EventType.MouseUp,destination);Render();}
 IEnumerator Start(){yield return null;yield return null;try{RunChecks();EditorApplication.isPlaying=false;}catch(Exception e){Debug.LogException(e);Directory.CreateDirectory("Docs/IslandSystem");File.WriteAllText("Docs/IslandSystem/REVIEW.txt",string.Join("\n",passed)+"\n"+e);EditorApplication.Exit(2);}}
 void RunChecks(){
 Directory.CreateDirectory("Docs/IslandSystem");ui=FindAnyObjectByType<Workbench>();ui.BackgroundReview=true;ui.SavePathOverride=Path.GetFullPath("Logs/island-review-draft.json");Set("draft",new Draft());Set("status","新程序 · 编辑后自动保存");viewType=typeof(Editor).Assembly.GetType("UnityEditor.GameView");view=EditorWindow.GetWindow(viewType);
 var walkers=FindObjectsByType<LighthouseWalker>();var enabled=walkers.Select(w=>w.enabled).ToArray();float time=Time.timeScale;ui.HandleKey(KeyCode.Tab);Render();Render();Assert(Get<bool>("open")&&walkers.All(w=>!w.enabled),"Tab opens and blocks existing character input");Assert(Data.blocks.Count==0,"Free mode starts empty");Capture("01-Free");ui.HandleKey(KeyCode.Tab);Assert(!Get<bool>("open")&&walkers.Select((w,i)=>w.enabled==enabled[i]).All(x=>x),"Tab closes and restores input state");Render();Click(new Vector2(width-85,38));Assert(Get<bool>("open"),"HUD system button opens workbench");
 Drag(0,new Vector2(445,150));Assert(Data.blocks.Count==1&&Data.blocks[0].kind==0,"Drag entry from library");var start=Data.blocks[0];Drag(2,Header(start));Assert(Data.blocks.Count==2&&Data.blocks[1].kind==2&&!Data.blocks[1].detached,"Snap repeat after entry");var loop=Data.blocks[1];Drag(3,Slot(loop));Assert(loop.children.Count==1&&loop.children[0].kind==3,"Nest wait inside repeat");var wait=loop.children[0];Drag(4,Slot(loop));Assert(loop.children.Count==2&&loop.children[1].kind==4,"Nest conditional inside repeat");var branch=loop.children[1];Drag(5,Header(branch));Assert(branch.condition!=null&&branch.condition.kind==5,"Snap hexagonal sensor into condition interface");Drag(1,Slot(branch));Assert(branch.children.Count==1,"Nest action inside conditional");Assert(ProgramValidator.Validate(Data).Count==0,"Nested program validates");string beforeIncompatible=ProgramCodec.Write(Data);Drag(5,Header(start));Assert(ProgramCodec.Write(Data)==beforeIncompatible&&Get<string>("report").Contains("不兼容"),"Incompatible reporter-to-statement connection is refused");
 // Numeric and option controls receive only virtual IMGUI events.
 var lr=Get<Dictionary<Block,Rect>>("rects")[loop];Click(new Vector2(395+lr.xMax-40,110+lr.y+20));ui.ReviewFocus="number-"+loop.id;Send(new Event{type=EventType.KeyDown,keyCode=KeyCode.Backspace});Send(new Event{type=EventType.KeyDown,keyCode=KeyCode.Alpha4,character='4'});ui.ReviewFocus=null;Assert(loop.value=="4","Edit focused numeric field with virtual keyboard events");var br=Get<Dictionary<Block,Rect>>("rects")[branch];Click(new Vector2(395+br.xMax-32,110+br.y+20));Assert(branch.condition.value=="false","Edit simulated boolean option");Click(new Vector2(395+br.xMax-32,110+br.y+20));
 Call("Check",false);string stable=ProgramCodec.Write(Data);Click(new Vector2(490,80));Assert(Get<bool>("guided")&&ProgramCodec.Write(Data)==stable,"Guided mode preserves graph and parameters");Click(new Vector2(1055,385));Click(new Vector2(1055,385));Assert(Get<int>("hint")==2,"Guided task reveals hints without assembling blocks");Capture("03-Guided");Click(new Vector2(375,80));Assert(!Get<bool>("guided")&&ProgramCodec.Write(Data)==stable,"Free mode restores full workspace");
 // Context duplicate, undo and redo use the same UI command path.
 Click(Header(wait),1);var wr=Get<Rect>("context");Click(new Vector2(395+wr.x+60,110+wr.y+15));Assert(loop.children.Count==3,"Right-click duplicate");ui.HandleKey(KeyCode.Z,true);Assert(Data.blocks[1].children.Count==2,"Undo duplicate");ui.HandleKey(KeyCode.Y,true);Assert(Data.blocks[1].children.Count==3,"Redo duplicate");ui.HandleKey(KeyCode.Z,true);Render();loop=Data.blocks[1];wait=loop.children[0];branch=loop.children[1];Click(Header(wait));ui.HandleKey(KeyCode.Delete);Assert(loop.children.Count==1&&loop.children[0].kind==4,"Delete preserves following connected blocks");ui.HandleKey(KeyCode.Z,true);Render();loop=Data.blocks[1];wait=loop.children[0];branch=loop.children[1];
 Click(Header(wait),1);var helpRect=Get<Rect>("context");Click(new Vector2(395+helpRect.x+60,110+helpRect.y+79));Assert(Get<string>("report").Contains("1–60"),"Context explanation uses block definition");Click(Header(wait),1);var deleteRect=Get<Rect>("context");Click(new Vector2(395+deleteRect.x+60,110+deleteRect.y+47));Assert(loop.children.Count==1&&loop.children[0].kind==4,"Context delete retains following instructions");ui.HandleKey(KeyCode.Z,true);Render();loop=Data.blocks[1];wait=loop.children[0];branch=loop.children[1];
 // Reorder from inside a control to the middle of the root sequence.
 Pointer(EventType.MouseDown,Header(wait));Pointer(EventType.MouseDrag,Header(Data.blocks[0]));Pointer(EventType.MouseUp,Header(Data.blocks[0]));Assert(Data.blocks.Count==3&&Data.blocks[1].kind==3,"Move and insert existing block between instructions");ui.HandleKey(KeyCode.Z,true);Render();
 Vector2 oldPan=Get<Vector2>("pan");Click(new Vector2(1000,470));Pointer(EventType.MouseDown,new Vector2(1000,470));Pointer(EventType.MouseDrag,new Vector2(1020,490));Pointer(EventType.MouseUp,new Vector2(1020,490));Assert(Get<Vector2>("pan")!=oldPan,"Pan blank workspace");float oldZoom=Get<float>("zoom");Send(new Event{type=EventType.ScrollWheel,mousePosition=new Vector2(1000,470),delta=new Vector2(0,-2)});Assert(Get<float>("zoom")>oldZoom,"Zoom workspace");Set("pan",new Vector2(20,20));Set("zoom",1f);Render();
 Set("category",2);ui.HandleKey(KeyCode.F5);Assert(Get<string>("report").Contains("编辑器执行预览"),"F5 produces editor-only execution trace");Capture("02-Nested");Call("Save");var saved=ProgramCodec.Read(File.ReadAllText(ui.SavePathOverride));Assert(ProgramCodec.Write(saved)==ProgramCodec.Write(Data),"Versioned nested draft roundtrip and real disk save");ui.HandleKey(KeyCode.Escape);Set("draft",new Draft());Call("LoadDraft");Assert(ProgramCodec.Write(Data)==ProgramCodec.Write(saved),"Actual load path restores draft from isolated disk file");ui.HandleKey(KeyCode.Tab);Assert(ProgramCodec.Write(Data)==ProgramCodec.Write(saved),"Close and reopen preserves draft");
 // Validation cases are deliberately malformed, never sent to real game systems.
 var valid=ProgramCodec.Read(ProgramCodec.Write(Data));Data.blocks[1].value="999";ui.HandleKey(KeyCode.F5);Assert(Get<string>("report").Contains("1–20"),"Loop limit error identifies offending block");Capture("04-Validation");Set("draft",new Draft());Call("Check",false);Assert(Get<string>("report").Contains("缺少启动"),"Missing event is detected");Set("draft",ProgramCodec.Read(ProgramCodec.Write(valid)));Data.blocks[1].children.Clear();Assert(ProgramValidator.Validate(Data).Any(i=>i.message.Contains("内部为空")),"Empty control is detected");Set("draft",ProgramCodec.Read(ProgramCodec.Write(valid)));Data.blocks[1].detached=true;Assert(ProgramValidator.Validate(Data).Any(i=>i.message.Contains("断开")),"Disconnected stack is detected");Set("draft",ProgramCodec.Read(ProgramCodec.Write(valid)));Data.blocks[1].children[1].condition=new Block{kind=6,value="NaN"};Assert(ProgramValidator.Validate(Data).Any(i=>i.message.Contains("有限数字")),"Invalid comparison parameter is detected");Set("draft",valid);
 var numericDraft=new Draft();numericDraft.blocks.Add(new Block{kind=0});var numericLoop=new Block{kind=2,value="2.0"};numericLoop.children.Add(new Block{kind=3,value="1"});numericDraft.blocks.Add(numericLoop);Set("draft",numericDraft);ui.HandleKey(KeyCode.F5);Assert(Get<string>("report").Split(new[]{"等待（秒）"},StringSplitOptions.None).Length==3,"Integer-valued decimal repeat parameter previews correctly");
 var bounded=new Draft();bounded.blocks.Add(new Block{kind=0});var outer=new Block{kind=2,value="20"};bounded.blocks.Add(outer);var cursor=outer;for(int i=0;i<6;i++){var child=new Block{kind=2,value="20"};cursor.children.Add(child);cursor=child;}cursor.children.Add(new Block{kind=3,value="1"});Set("draft",bounded);ui.HandleKey(KeyCode.F5);Assert(Get<string>("report").Contains("400条安全上限"),"Large nested preview stops at safety budget");Set("draft",valid);
 bool rejected=false;try{ProgramCodec.Read("{\"version\":99}");}catch{rejected=true;}Assert(rejected,"Unsupported save version rejected");string goodPath=ui.SavePathOverride;ui.SavePathOverride=Path.GetFullPath("Logs/missing-review-directory/draft.json");Call("Save");Assert(Get<string>("status").Contains("保存失败"),"Save failure is reported truthfully");ui.SavePathOverride=goodPath;Call("Save");var corruptPath=Path.GetFullPath("Logs/island-review-corrupt.json");File.WriteAllText(corruptPath,"not valid json");ui.SavePathOverride=corruptPath;Call("LoadDraft");Call("Save");Assert(Get<string>("status").Contains("恢复失败")&&File.ReadAllText(corruptPath)=="not valid json","Corrupt draft is reported and preserved without edits");ui.SavePathOverride=goodPath;Call("LoadDraft");
 Set("pan",new Vector2(20,20));Set("zoom",1f);ui.HandleKey(KeyCode.F5);width=960;height=540;Capture("05-Compact");width=1600;height=900;Capture("06-Large");width=1280;height=720;Assert(Time.timeScale==time,"World time scale unchanged");ui.HandleKey(KeyCode.Escape);Assert(walkers.Select((w,i)=>w.enabled==enabled[i]).All(x=>x),"Final close restores original control state");File.WriteAllText("Docs/IslandSystem/REVIEW.txt",string.Join("\n",passed)+"\nAll input was internal virtual UI events in batch mode. No desktop control or mouse capture. Screenshots are offscreen Play Mode renders.");
 }
}
[InitializeOnLoad] public static class WorkbenchReviewEntry {
 static WorkbenchReviewEntry(){if(SessionState.GetBool("IslandUIReview",false))EditorApplication.playModeStateChanged+=Attach;}
 [MenuItem("Island System/Run background UI review")]
 public static void Run(){if(!Application.isBatchMode)throw new Exception("Review requires -batchmode; desktop interaction is disabled.");EditorSceneManager.OpenScene("Assets/Scenes/Lighthouse_Coast_ArtBenchmark_V01.unity");EnsureUIScene();SessionState.SetBool("IslandUIReview",true);EditorApplication.playModeStateChanged+=Attach;EditorApplication.isPlaying=true;}
 static void EnsureUIScene(){const string path="Assets/IslandSystem/Scenes/IslandSystem_UI.unity";if(File.Exists(path))return;Directory.CreateDirectory("Assets/IslandSystem/Scenes");AssetDatabase.Refresh();var scene=EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Additive);var root=new GameObject("荒岛智能系统");SceneManager.MoveGameObjectToScene(root,scene);root.AddComponent<Workbench>();var cameraObject=new GameObject("Standalone UI background");SceneManager.MoveGameObjectToScene(cameraObject,scene);var camera=cameraObject.AddComponent<Camera>();camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=new Color(.24f,.35f,.34f);EditorSceneManager.SaveScene(scene,path);EditorSceneManager.CloseScene(scene,true);}
 static void Attach(PlayModeStateChange state){if(state==PlayModeStateChange.EnteredPlayMode)new GameObject("Headless UI review").AddComponent<WorkbenchReview>();if(state==PlayModeStateChange.EnteredEditMode){SessionState.SetBool("IslandUIReview",false);EditorApplication.Exit(0);}}
}
}
